function xcOpts(r, col){ const same = shuffle(XC.filter(z => z !== r && z[0] === r[0])), rest = shuffle(XC.filter(z => z[0] !== r[0]));
  const out = [], seen = new Set([TEN(r[col])]); same.concat(rest).forEach(z => { if (out.length < 3 && !seen.has(TEN(z[col]))){ seen.add(TEN(z[col])); out.push(z[col]); } }); return [r[col]].concat(out); }
function xcCase(t){ const r = pick(XC.filter(z => z[0] === t)), how = Math.random() < 0.5;
  return {k:'case', t, stem:r[1], parts:[
    {q:XCQ.dx, o:xcOpts(r, 2), x:r[3]},
    {q:XCQ.mech, o:xcOpts(r, 4), x:q3x("{d}: {m}.|{d} : {m}.|{d}: {m}.", {d:r[2], m:r[4]})},
    {q:XCQ.drug, o:xcOpts(r, 5), x:r[6]},
    how ? {q:XCQ.how, o:xcOpts(r, 7), x:q3x("Watch for: {a}.|Attention : {a}.|Achtung: {a}.", {a:r[8]})} : {q:XCQ.ae, o:xcOpts(r, 8), x:q3x("Mechanism: {m}.|Mécanisme : {m}.|Wirkmechanismus: {m}.", {m:r[7]})}]}; }
const X3BANK = ['endo', 'cvresp', 'neuro', 'gimsk'].map(t => ({t, w:3, tab:{rows:XC.filter(z => z[0] === t), c:[2, 4, 5, 8], h:['', '', "Diagnosis|Diagnostic|Diagnose", '', "Mechanism|Mécanisme|Mechanismus", "First-line drug|Traitement de 1re intention|Mittel der Wahl", '', '', "Watch for|Attention|Achtung"]}, gen(){ return xcCase(t); }}));
