function xpTab(head, rows){ return () => `<table class="sxtbl xptbl"><thead><tr>${head.map(h => `<th>${esc(T(h))}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, j) => `<${j ? 'td' : 'th'}>${esc(T(c))}</${j ? 'td' : 'th'}>`).join('')}</tr>`).join('')}</tbody></table>`; }
const XP = (t, stem, parts, more) => Object.assign({t, k:'case', stem, parts:parts.map(p => ({q:p[0], o:p[1], x:p[2]}))}, more || {});
const X4BANK = [
  XP('bio', "Researchers measured the initial rate of an enzyme at several substrate concentrations, with and without 2 µM of compound X (table).|Des chercheurs ont mesuré la vitesse initiale d'une enzyme à plusieurs concentrations de substrat, avec et sans 2 µM de composé X (tableau).|Forschende maßen die Anfangsgeschwindigkeit eines Enzyms bei mehreren Substratkonzentrationen, mit und ohne 2 µM Substanz X (Tabelle).", [
    ["What kind of inhibitor is X?|Quel type d'inhibiteur est X ?|Welche Art von Hemmstoff ist X?", ["Competitive|Compétitif|Kompetitiv", "Non-competitive|Non compétitif|Nichtkompetitiv", "Uncompetitive|Incompétitif|Unkompetitiv", "Irreversible, covalent|Irréversible, covalent|Irreversibel, kovalent"], "At 50 mM substrate the rate almost reaches the uninhibited maximum: Vmax is unchanged while the substrate concentration for half-maximal rate rises (Km from about 1 to 3 mM).|À 50 mM de substrat, la vitesse atteint presque le maximum sans inhibiteur : Vmax inchangée, alors que la concentration de demi-vitesse augmente (Km d'environ 1 à 3 mM).|Bei 50 mM Substrat erreicht die Geschwindigkeit fast das ungehemmte Maximum: Vmax unverändert, während die Konzentration für halbmaximale Geschwindigkeit steigt (Km von etwa 1 auf 3 mM)."],
    ["What would most likely overcome the inhibition?|Qu'est-ce qui lèverait le plus probablement l'inhibition ?|Was würde die Hemmung am ehesten aufheben?", ["Raising the substrate concentration|Augmenter la concentration de substrat|Die Substratkonzentration erhöhen", "Adding more of compound X|Ajouter plus de composé X|Mehr Substanz X zugeben", "Lowering the temperature|Baisser la température|Die Temperatur senken", "Removing the cofactor|Retirer le cofacteur|Den Cofaktor entfernen"], "Competitive inhibitors compete for the active site, so excess substrate outcompetes them.|Les inhibiteurs compétitifs se disputent le site actif : un excès de substrat les déplace.|Kompetitive Hemmstoffe konkurrieren um das aktive Zentrum; Substratüberschuss verdrängt sie."],
    ["On a Lineweaver–Burk plot, the lines with and without X would…|Sur un graphique de Lineweaver–Burk, les droites avec et sans X…|Im Lineweaver-Burk-Diagramm würden sich die Geraden mit und ohne X …", ["cross on the y-axis|se croisent sur l'axe des y|auf der y-Achse schneiden", "cross on the x-axis|se croisent sur l'axe des x|auf der x-Achse schneiden", "be parallel|sont parallèles|parallel verlaufen", "cross to the left of the y-axis, above the x-axis|se croisent à gauche de l'axe des y, au-dessus de l'axe des x|links der y-Achse oberhalb der x-Achse schneiden"], "Same Vmax means the same y-intercept (1/Vmax); only the slope (Km/Vmax) increases.|Même Vmax = même ordonnée à l'origine (1/Vmax) ; seule la pente (Km/Vmax) augmente.|Gleiche Vmax = gleicher y-Achsenabschnitt (1/Vmax); nur die Steigung (Km/Vmax) nimmt zu."]],
    {stemh:xpTab(["[S] (mM)|[S] (mM)|[S] (mM)", "v without X|v sans X|v ohne X", "v with X|v avec X|v mit X"], [["0.5|0,5|0,5", "33", "14"], ["1", "50", "25"], ["2", "67", "40"], ["10", "91", "77"], ["50", "98", "94"]])}),
  XP('bio', "Liver cells raise cAMP when glucagon binds its Gs-coupled receptor. A mutant cell line lacks functional Gαs. Forskolin activates adenylyl cyclase directly; theophylline inhibits phosphodiesterase.|Les hépatocytes augmentent l'AMPc quand le glucagon se lie à son récepteur couplé à Gs. Une lignée mutante n'a pas de Gαs fonctionnelle. La forskoline active directement l'adénylate cyclase ; la théophylline inhibe la phosphodiestérase.|Leberzellen erhöhen cAMP, wenn Glucagon an seinen Gs-gekoppelten Rezeptor bindet. Eine Mutantenlinie hat kein funktionelles Gαs. Forskolin aktiviert die Adenylatcyclase direkt; Theophyllin hemmt die Phosphodiesterase.", [
    ["In the mutant cells, glucagon will…|Dans les cellules mutantes, le glucagon va…|In den Mutantenzellen wird Glucagon …", ["bind its receptor but not raise cAMP|se fixer à son récepteur sans augmenter l'AMPc|an seinen Rezeptor binden, aber cAMP nicht erhöhen", "fail to bind its receptor|ne pas se fixer à son récepteur|nicht an seinen Rezeptor binden", "raise cAMP normally|augmenter normalement l'AMPc|cAMP normal erhöhen", "raise IP₃ instead of cAMP|augmenter l'IP₃ au lieu de l'AMPc|IP₃ statt cAMP erhöhen"], "The receptor is intact, but the signal cannot reach adenylyl cyclase without Gαs.|Le récepteur est intact, mais le signal ne peut atteindre l'adénylate cyclase sans Gαs.|Der Rezeptor ist intakt, aber ohne Gαs erreicht das Signal die Adenylatcyclase nicht."],
    ["What does forskolin do in the mutant cells?|Que fait la forskoline dans les cellules mutantes ?|Was bewirkt Forskolin in den Mutantenzellen?", ["Raises cAMP – it bypasses the G protein|Augmente l'AMPc – elle contourne la protéine G|Erhöht cAMP – es umgeht das G-Protein", "Nothing, because Gαs is missing|Rien, car la Gαs manque|Nichts, weil Gαs fehlt", "Lowers cAMP|Diminue l'AMPc|Senkt cAMP", "Blocks the glucagon receptor|Bloque le récepteur du glucagon|Blockiert den Glucagonrezeptor"], "Forskolin acts on adenylyl cyclase itself, downstream of the defect.|La forskoline agit sur l'adénylate cyclase elle-même, en aval du défaut.|Forskolin wirkt direkt an der Adenylatcyclase, unterhalb des Defekts."],
    ["In normal cells, adding theophylline to glucagon makes the cAMP signal…|Dans les cellules normales, ajouter la théophylline au glucagon rend le signal AMPc…|In normalen Zellen macht Theophyllin zusätzlich zu Glucagon das cAMP-Signal …", ["larger and longer-lasting|plus fort et plus durable|stärker und länger anhaltend", "smaller|plus faible|schwächer", "unchanged|inchangé|unverändert", "disappear|disparaître|verschwinden"], "Phosphodiesterase breaks cAMP down to AMP; blocking it lets cAMP accumulate.|La phosphodiestérase dégrade l'AMPc en AMP ; la bloquer laisse l'AMPc s'accumuler.|Die Phosphodiesterase baut cAMP zu AMP ab; ihre Hemmung lässt cAMP ansteigen."]],
    {vb:{t:"G-protein signalling chains: Cell signalling (C6).|Chaînes de signalisation des protéines G : Signalisation cellulaire (C6).|G-Protein-Signalketten: Zellsignale (C6).", d:'signalling'}}),
  XP('bio', "A phosphate buffer (pKa 6.8 for H₂PO₄⁻ ⇌ HPO₄²⁻ + H⁺) is prepared with [HPO₄²⁻] : [H₂PO₄⁻] = 10 : 1.|Un tampon phosphate (pKa 6,8 pour H₂PO₄⁻ ⇌ HPO₄²⁻ + H⁺) est préparé avec [HPO₄²⁻] : [H₂PO₄⁻] = 10 : 1.|Ein Phosphatpuffer (pKs 6,8 für H₂PO₄⁻ ⇌ HPO₄²⁻ + H⁺) wird mit [HPO₄²⁻] : [H₂PO₄⁻] = 10 : 1 angesetzt.", [
    ["What is the pH of the buffer?|Quel est le pH du tampon ?|Welchen pH hat der Puffer?", ["7.8|7,8|7,8", "6.8|6,8|6,8", "5.8|5,8|5,8", "8.8|8,8|8,8"], "pH = pKa + log(base/acid) = 6.8 + log 10 = 7.8.|pH = pKa + log(base/acide) = 6,8 + log 10 = 7,8.|pH = pKs + log(Base/Säure) = 6,8 + log 10 = 7,8."],
    ["At which pH does this buffer resist added acid and base best?|À quel pH ce tampon résiste-t-il le mieux aux ajouts d'acide et de base ?|Bei welchem pH puffert dieses System Säure und Base am besten?", ["6.8|6,8|6,8", "7.8|7,8|7,8", "7.4|7,4|7,4", "5.0|5,0|5,0"], "Buffer capacity is greatest when pH = pKa (equal acid and base).|Le pouvoir tampon est maximal quand pH = pKa (acide et base en quantités égales).|Die Pufferkapazität ist bei pH = pKs am größten (gleich viel Säure und Base)."],
    ["A little HCl is added. Which species increases?|On ajoute un peu de HCl. Quelle espèce augmente ?|Etwas HCl wird zugegeben. Welche Spezies nimmt zu?", ["H₂PO₄⁻|H₂PO₄⁻|H₂PO₄⁻", "HPO₄²⁻|HPO₄²⁻|HPO₄²⁻", "PO₄³⁻|PO₄³⁻|PO₄³⁻", "OH⁻|OH⁻|OH⁻"], "The base form takes up the H⁺: HPO₄²⁻ + H⁺ → H₂PO₄⁻, so the pH falls only slightly.|La forme basique capte l'H⁺ : HPO₄²⁻ + H⁺ → H₂PO₄⁻ ; le pH baisse donc peu.|Die Basenform nimmt das H⁺ auf: HPO₄²⁻ + H⁺ → H₂PO₄⁻; der pH sinkt nur wenig."]]),
  XP('phy', "Substance Y is infused until its plasma concentration is steady at 2 mg/mL. Inulin clearance is 120 mL/min, urine flow 1 mL/min and urine concentration of Y 240 mg/mL. Y is not bound to plasma proteins.|La substance Y est perfusée jusqu'à une concentration plasmatique stable de 2 mg/mL. La clairance de l'inuline est de 120 mL/min, le débit urinaire de 1 mL/min et la concentration urinaire de Y de 240 mg/mL. Y n'est pas liée aux protéines.|Substanz Y wird infundiert, bis ihre Plasmakonzentration stabil 2 mg/ml beträgt. Inulin-Clearance 120 ml/min, Urinfluss 1 ml/min, Urinkonzentration von Y 240 mg/ml. Y ist nicht proteingebunden.", [
    ["What is the clearance of Y?|Quelle est la clairance de Y ?|Wie hoch ist die Clearance von Y?", ["120 mL/min|120 mL/min|120 ml/min", "240 mL/min|240 mL/min|240 ml/min", "60 mL/min|60 mL/min|60 ml/min", "480 mL/min|480 mL/min|480 ml/min"], "C = U × V ÷ P = 240 × 1 ÷ 2 = 120 mL/min.|C = U × V ÷ P = 240 × 1 ÷ 2 = 120 mL/min.|C = U × V ÷ P = 240 × 1 ÷ 2 = 120 ml/min."],
    ["What best describes how the kidney handles Y?|Comment le rein traite-t-il Y ?|Wie behandelt die Niere Y?", ["Filtered only – neither reabsorbed nor secreted overall|Seulement filtrée – ni réabsorbée ni sécrétée au total|Nur filtriert – netto weder resorbiert noch sezerniert", "Filtered and partly reabsorbed|Filtrée et en partie réabsorbée|Filtriert und teilweise resorbiert", "Filtered and secreted|Filtrée et sécrétée|Filtriert und sezerniert", "Not filtered at all|Pas filtrée du tout|Gar nicht filtriert"], "Its clearance equals the GFR (inulin clearance), like inulin itself.|Sa clairance égale le DFG (clairance de l'inuline), comme l'inuline.|Ihre Clearance entspricht der GFR (Inulin-Clearance), wie Inulin selbst."],
    ["Another substance has a clearance of 600 mL/min. It is most likely…|Une autre substance a une clairance de 600 mL/min. Elle est probablement…|Eine andere Substanz hat eine Clearance von 600 ml/min. Sie wird am ehesten …", ["filtered and actively secreted (like PAH)|filtrée et activement sécrétée (comme le PAH)|filtriert und aktiv sezerniert (wie PAH)", "filtered and reabsorbed (like glucose)|filtrée et réabsorbée (comme le glucose)|filtriert und resorbiert (wie Glucose)", "only filtered|seulement filtrée|nur filtriert", "too large to be filtered|trop grosse pour être filtrée|zu groß für die Filtration"], "A clearance above the GFR means secretion; PAH clearance approximates renal plasma flow.|Une clairance supérieure au DFG signifie une sécrétion ; la clairance du PAH approche le débit plasmatique rénal.|Eine Clearance über der GFR bedeutet Sekretion; die PAH-Clearance nähert den renalen Plasmafluss an."]]),
  XP('phy', "A trained cyclist at rest has a heart rate of 50/min and a stroke volume of 100 mL. During maximal exercise her heart rate is 180/min and stroke volume 140 mL.|Une cycliste entraînée a au repos une fréquence cardiaque de 50/min et un volume d'éjection systolique de 100 mL. À l'effort maximal, fréquence 180/min et VES 140 mL.|Eine trainierte Radfahrerin hat in Ruhe eine Herzfrequenz von 50/min und ein Schlagvolumen von 100 ml. Bei maximaler Belastung: Herzfrequenz 180/min, Schlagvolumen 140 ml.", [
    ["Her cardiac output at rest is…|Son débit cardiaque au repos est de…|Ihr Herzzeitvolumen in Ruhe beträgt …", ["5.0 L/min|5,0 L/min|5,0 l/min", "7.0 L/min|7,0 L/min|7,0 l/min", "2.0 L/min|2,0 L/min|2,0 l/min", "50 L/min|50 L/min|50 l/min"], "CO = HR × SV = 50 × 0.1 L = 5.0 L/min.|DC = FC × VES = 50 × 0,1 L = 5,0 L/min.|HZV = HF × SV = 50 × 0,1 l = 5,0 l/min."],
    ["Her maximal cardiac output is…|Son débit cardiaque maximal est de…|Ihr maximales Herzzeitvolumen beträgt …", ["25.2 L/min|25,2 L/min|25,2 l/min", "18.0 L/min|18,0 L/min|18,0 l/min", "14.0 L/min|14,0 L/min|14,0 l/min", "32.0 L/min|32,0 L/min|32,0 l/min"], "180 × 0.14 L = 25.2 L/min – a fivefold rise.|180 × 0,14 L = 25,2 L/min – multiplié par cinq.|180 × 0,14 l = 25,2 l/min – eine Verfünffachung."],
    ["What mainly explains the larger stroke volume during exercise?|Qu'est-ce qui explique surtout l'augmentation du VES à l'effort ?|Was erklärt vor allem das größere Schlagvolumen bei Belastung?", ["Sympathetic inotropy plus greater venous return (Frank–Starling)|Inotropie sympathique et retour veineux accru (Frank–Starling)|Sympathische Inotropie plus mehr venöser Rückstrom (Frank-Starling)", "Higher afterload|Postcharge plus élevée|Höhere Nachlast", "Slower heart rate allowing more filling|Fréquence plus lente permettant un meilleur remplissage|Langsamere Frequenz mit besserer Füllung", "Vagal stimulation|Stimulation vagale|Vagusstimulation"], "Noradrenaline on β1 raises contractility, and the muscle pump increases preload.|La noradrénaline sur les β1 augmente la contractilité et la pompe musculaire accroît la précharge.|Noradrenalin an β1 steigert die Kontraktilität, die Muskelpumpe erhöht die Vorlast."]]),
  XP('phy', "An isolated nerve is studied. Lidocaine applied to one segment stops action potentials from passing it. In a second experiment the extracellular K⁺ concentration is raised from 4 to 10 mmol/L.|On étudie un nerf isolé. La lidocaïne appliquée sur un segment empêche les potentiels d'action de le franchir. Dans une seconde expérience, le K⁺ extracellulaire passe de 4 à 10 mmol/L.|Ein isolierter Nerv wird untersucht. Lidocain auf einem Abschnitt verhindert, dass Aktionspotenziale ihn passieren. In einem zweiten Versuch wird das extrazelluläre K⁺ von 4 auf 10 mmol/l erhöht.", [
    ["How does lidocaine block conduction?|Comment la lidocaïne bloque-t-elle la conduction ?|Wie blockiert Lidocain die Erregungsleitung?", ["It blocks voltage-gated Na⁺ channels from inside|Elle bloque les canaux Na⁺ voltage-dépendants par l'intérieur|Es blockiert spannungsgesteuerte Na⁺-Kanäle von innen", "It opens K⁺ channels|Elle ouvre des canaux K⁺|Es öffnet K⁺-Kanäle", "It inhibits the Na⁺/K⁺-ATPase|Elle inhibe la Na⁺/K⁺-ATPase|Es hemmt die Na⁺/K⁺-ATPase", "It blocks Ca²⁺ channels at the synapse|Elle bloque les canaux Ca²⁺ synaptiques|Es blockiert synaptische Ca²⁺-Kanäle"], "Local anaesthetics enter the axon and bind open/inactivated Na⁺ channels, so no upstroke can occur.|Les anesthésiques locaux pénètrent dans l'axone et se fixent aux canaux Na⁺ ouverts/inactivés : pas de dépolarisation possible.|Lokalanästhetika dringen ins Axon ein und binden offene/inaktivierte Na⁺-Kanäle; kein Aufstrich möglich."],
    ["Which fibres are blocked first by a low concentration?|Quelles fibres sont bloquées en premier à faible concentration ?|Welche Fasern blockiert eine niedrige Konzentration zuerst?", ["Small pain fibres (Aδ and C)|Petites fibres de la douleur (Aδ et C)|Dünne Schmerzfasern (Aδ und C)", "Large motor fibres (Aα)|Grosses fibres motrices (Aα)|Dicke motorische Fasern (Aα)", "All fibres equally|Toutes les fibres de la même façon|Alle Fasern gleich", "Only myelinated motor fibres|Seulement les fibres motrices myélinisées|Nur myelinisierte motorische Fasern"], "Thin fibres need fewer blocked channels or nodes to fail, so pain goes before touch and movement.|Les fibres fines cèdent avec moins de canaux ou de nœuds bloqués : la douleur disparaît avant le toucher et la motricité.|Dünne Fasern versagen schon bei weniger blockierten Kanälen oder Schnürringen; Schmerz verschwindet vor Berührung und Motorik."],
    ["Raising extracellular K⁺ makes the resting membrane potential…|L'augmentation du K⁺ extracellulaire rend le potentiel de repos…|Mehr extrazelluläres K⁺ macht das Ruhemembranpotenzial …", ["less negative (depolarised)|moins négatif (dépolarisé)|weniger negativ (depolarisiert)", "more negative (hyperpolarised)|plus négatif (hyperpolarisé)|negativer (hyperpolarisiert)", "unchanged|inchangé|unverändert", "positive|positif|positiv"], "The K⁺ gradient shrinks, so E_K and the resting potential move towards zero (Nernst); sustained depolarisation later inactivates Na⁺ channels.|Le gradient de K⁺ diminue : E_K et le potentiel de repos se rapprochent de zéro (Nernst) ; une dépolarisation prolongée inactive ensuite les canaux Na⁺.|Der K⁺-Gradient wird kleiner, E_K und Ruhepotenzial rücken Richtung null (Nernst); anhaltende Depolarisation inaktiviert dann Na⁺-Kanäle."]]),
  XP('phy', "In an experiment, the pituitary of rats is removed (hypophysectomy). In other, normal rats the synthetic glucocorticoid dexamethasone is given.|Dans une expérience, on retire l'hypophyse de rats (hypophysectomie). D'autres rats normaux reçoivent de la dexaméthasone, un glucocorticoïde de synthèse.|In einem Versuch wird Ratten die Hypophyse entfernt (Hypophysektomie). Anderen, normalen Ratten wird das synthetische Glukokortikoid Dexamethason gegeben.", [
    ["After hypophysectomy, plasma cortisol (corticosterone in rats)…|Après hypophysectomie, le cortisol plasmatique (corticostérone chez le rat)…|Nach der Hypophysektomie wird das Plasmacortisol (bei Ratten Corticosteron) …", ["falls|diminue|sinken", "rises|augmente|steigen", "is unchanged|reste inchangé|unverändert bleiben", "first rises, then falls|augmente puis diminue|erst steigen, dann sinken"], "Without ACTH the adrenal cortex is no longer stimulated (and atrophies).|Sans ACTH, le cortex surrénalien n'est plus stimulé (et s'atrophie).|Ohne ACTH wird die Nebennierenrinde nicht mehr stimuliert (und atrophiert)."],
    ["What happens to hypothalamic CRH after hypophysectomy?|Que devient la CRH hypothalamique après hypophysectomie ?|Was geschieht mit dem hypothalamischen CRH nach der Hypophysektomie?", ["It rises – negative feedback from cortisol is lost|Elle augmente – le rétrocontrôle négatif du cortisol disparaît|Es steigt – die negative Rückkopplung durch Cortisol fehlt", "It falls|Elle diminue|Es sinkt", "It is unchanged|Elle reste inchangée|Es bleibt unverändert", "It stops being made|Elle n'est plus produite|Es wird nicht mehr gebildet"], "Low cortisol removes the brake on the hypothalamus.|Le cortisol bas lève le frein sur l'hypothalamus.|Niedriges Cortisol löst die Bremse am Hypothalamus."],
    ["In the normal rats, dexamethasone makes ACTH and endogenous cortisol…|Chez les rats normaux, la dexaméthasone fait varier l'ACTH et le cortisol endogène…|Bei den normalen Ratten bewirkt Dexamethason, dass ACTH und körpereigenes Cortisol …", ["both fall|les deux diminuent|beide sinken", "both rise|les deux augmentent|beide steigen", "ACTH rises, cortisol falls|ACTH augmente, cortisol diminue|ACTH steigt, Cortisol sinkt", "ACTH falls, cortisol rises|ACTH diminue, cortisol augmente|ACTH sinkt, Cortisol steigt"], "Dexamethasone mimics cortisol feedback on hypothalamus and pituitary – the basis of the dexamethasone suppression test.|La dexaméthasone imite le rétrocontrôle du cortisol sur l'hypothalamus et l'hypophyse – base du test de freinage.|Dexamethason ahmt die Cortisol-Rückkopplung an Hypothalamus und Hypophyse nach – Grundlage des Dexamethason-Hemmtests."]]),
  XP('gen', "In a family, an affected man has five children with an unaffected woman: all three daughters are affected and both sons are unaffected. The trait is seen in every generation.|Dans une famille, un homme atteint a cinq enfants avec une femme non atteinte : ses trois filles sont atteintes et ses deux fils indemnes. Le caractère apparaît à chaque génération.|In einer Familie hat ein betroffener Mann mit einer gesunden Frau fünf Kinder: alle drei Töchter sind betroffen, beide Söhne gesund. Das Merkmal tritt in jeder Generation auf.", [
    ["The most likely mode of inheritance is…|Le mode de transmission le plus probable est…|Der wahrscheinlichste Erbgang ist …", ["X-linked dominant|Dominant lié à l'X|X-chromosomal dominant", "X-linked recessive|Récessif lié à l'X|X-chromosomal rezessiv", "Autosomal recessive|Autosomique récessif|Autosomal rezessiv", "Mitochondrial|Mitochondrial|Mitochondrial"], "An affected father passes his X to every daughter and to no son.|Un père atteint transmet son X à toutes ses filles et à aucun fils.|Ein betroffener Vater gibt sein X an alle Töchter und an keinen Sohn weiter."],
    ["One affected daughter has a son with an unaffected man. Risk that the son is affected?|Une des filles atteintes a un fils avec un homme indemne. Risque que ce fils soit atteint ?|Eine betroffene Tochter bekommt mit einem gesunden Mann einen Sohn. Risiko, dass er betroffen ist?", ["50 %|50 %|50 %", "100 %|100 %|100 %", "25 %|25 %|25 %", "0 %|0 %|0 %"], "She is heterozygous (one affected X from her father), so each son has a 1 in 2 chance.|Elle est hétérozygote (un X atteint venant de son père) : chaque fils a 1 risque sur 2.|Sie ist heterozygot (ein betroffenes X vom Vater), daher hat jeder Sohn ein Risiko von 1 : 2."],
    ["Which disease follows this pattern?|Quelle maladie suit ce schéma ?|Welche Krankheit folgt diesem Muster?", ["X-linked hypophosphataemic rickets|Rachitisme hypophosphatémique lié à l'X|X-chromosomale hypophosphatämische Rachitis", "Duchenne muscular dystrophy|Myopathie de Duchenne|Muskeldystrophie Duchenne", "Cystic fibrosis|Mucoviscidose|Mukoviszidose", "Leber hereditary optic neuropathy|Neuropathie optique héréditaire de Leber|Lebersche hereditäre Optikusneuropathie"], "Duchenne is X-linked recessive, cystic fibrosis autosomal recessive and LHON mitochondrial (maternal).|Duchenne est récessive liée à l'X, la mucoviscidose autosomique récessive et la NOHL mitochondriale (maternelle).|Duchenne ist X-chromosomal rezessiv, Mukoviszidose autosomal rezessiv und LHON mitochondrial (mütterlich)."]],
    {vb:{t:"More pedigrees and recurrence risks: Inheritance & pedigrees (G3).|Plus d'arbres et de risques de récurrence : Hérédité et arbres généalogiques (G3).|Mehr Stammbäume und Wiederholungsrisiken: Vererbung & Stammbäume (G3).", d:'inherit'}}),
  XP('gen', "An E. coli isolate from a urinary infection grows on agar containing ampicillin. When clavulanic acid is added to the ampicillin, the bacterium no longer grows. Later the same resistance appears in a Klebsiella strain from another patient on the same ward.|Une souche d'E. coli d'une infection urinaire pousse sur gélose à l'ampicilline. Si l'on ajoute de l'acide clavulanique à l'ampicilline, elle ne pousse plus. Plus tard, la même résistance apparaît chez une souche de Klebsiella d'un autre patient du service.|Ein E.-coli-Isolat aus einem Harnwegsinfekt wächst auf ampicillinhaltigem Agar. Mit Clavulansäure zusätzlich zum Ampicillin wächst es nicht mehr. Später zeigt ein Klebsiella-Stamm eines anderen Patienten derselben Station dieselbe Resistenz.", [
    ["The resistance mechanism is most likely…|Le mécanisme de résistance est le plus probablement…|Der Resistenzmechanismus ist am ehesten …", ["a β-lactamase that hydrolyses ampicillin|une β-lactamase qui hydrolyse l'ampicilline|eine β-Laktamase, die Ampicillin spaltet", "an altered penicillin-binding protein|une protéine liant la pénicilline modifiée|ein verändertes Penicillin-bindendes Protein", "an efflux pump|une pompe d'efflux|eine Effluxpumpe", "loss of the cell wall|la perte de la paroi|der Verlust der Zellwand"], "Clavulanic acid restores activity, so the problem is an enzyme it can inhibit.|L'acide clavulanique rétablit l'activité : le problème est une enzyme qu'il peut inhiber.|Clavulansäure stellt die Wirkung wieder her – das Problem ist also ein Enzym, das sie hemmen kann."],
    ["How does clavulanic acid work?|Comment agit l'acide clavulanique ?|Wie wirkt Clavulansäure?", ["It binds and irreversibly inactivates β-lactamase (‘suicide inhibitor’)|Elle se lie à la β-lactamase et l'inactive de façon irréversible (inhibiteur « suicide »)|Sie bindet die β-Laktamase und inaktiviert sie irreversibel (‚Suizid-Inhibitor‘)", "It kills bacteria by itself|Elle tue seule les bactéries|Sie tötet Bakterien allein ab", "It blocks the ribosome|Elle bloque le ribosome|Sie blockiert das Ribosom", "It increases ampicillin absorption|Elle augmente l'absorption de l'ampicilline|Sie erhöht die Ampicillin-Resorption"], "On its own it has little antibacterial action; it protects the partner penicillin.|Seule, elle a peu d'activité antibactérienne ; elle protège la pénicilline associée.|Allein wirkt sie kaum antibakteriell; sie schützt das Partnerpenicillin."],
    ["How did the resistance most likely reach Klebsiella?|Comment la résistance a-t-elle le plus probablement atteint Klebsiella ?|Wie gelangte die Resistenz am ehesten zu Klebsiella?", ["Plasmid transfer by conjugation|Transfert de plasmide par conjugaison|Plasmidübertragung durch Konjugation", "Point mutation in Klebsiella|Mutation ponctuelle chez Klebsiella|Punktmutation bei Klebsiella", "Transfer by a fungal spore|Transmission par une spore fongique|Übertragung durch eine Pilzspore", "Induction by the antibiotic|Induction par l'antibiotique|Induktion durch das Antibiotikum"], "β-lactamase genes often sit on plasmids passed between different Gram-negative species through a sex pilus.|Les gènes de β-lactamases sont souvent portés par des plasmides transmis entre espèces Gram négatif via un pilus sexuel.|β-Laktamase-Gene liegen oft auf Plasmiden, die über einen Sexpilus zwischen gramnegativen Arten weitergegeben werden."]],
    {vb:{t:"Antibiotic targets and resistance: Antimicrobials (F3).|Cibles des antibiotiques et résistances : Anti-infectieux (F3).|Angriffspunkte und Resistenzen: Antiinfektiva (F3).", d:'antimicro'}}),
  XP('gen', "Mice born without a thymus (‘nude’ mice) are compared with normal mice. Both receive a skin graft from another mouse strain and are immunised with a protein antigen and with a bacterial capsular polysaccharide.|Des souris nées sans thymus (souris « nude ») sont comparées à des souris normales. Toutes reçoivent une greffe de peau d'une autre lignée et sont immunisées avec un antigène protéique et un polysaccharide capsulaire bactérien.|Mäuse ohne Thymus (‚Nacktmäuse‘) werden mit normalen Mäusen verglichen. Alle erhalten ein Hauttransplantat eines anderen Stammes und werden mit einem Proteinantigen und einem bakteriellen Kapselpolysaccharid immunisiert.", [
    ["In nude mice the foreign skin graft is…|Chez les souris nude, la greffe de peau étrangère est…|Bei Nacktmäusen wird das fremde Hauttransplantat …", ["accepted|acceptée|angenommen", "rejected faster than normal|rejetée plus vite que la normale|schneller als normal abgestoßen", "rejected normally|rejetée normalement|normal abgestoßen", "rejected by antibodies only|rejetée par les seuls anticorps|nur durch Antikörper abgestoßen"], "Graft rejection is mainly T-cell mediated, and T cells mature in the thymus.|Le rejet de greffe dépend surtout des lymphocytes T, qui mûrissent dans le thymus.|Transplantatabstoßung ist vor allem T-Zell-vermittelt, und T-Zellen reifen im Thymus."],
    ["Their antibody response to the protein antigen is…|Leur réponse anticorps à l'antigène protéique est…|Ihre Antikörperantwort auf das Proteinantigen ist …", ["severely reduced – no T-cell help|fortement réduite – pas d'aide T|stark vermindert – keine T-Zell-Hilfe", "normal|normale|normal", "increased|augmentée|erhöht", "IgE only|uniquement IgE|nur IgE"], "Protein antigens are T-dependent: B cells need CD40L and cytokines from helper T cells for class switching and memory.|Les antigènes protéiques sont T-dépendants : les lymphocytes B ont besoin du CD40L et des cytokines des T auxiliaires pour la commutation de classe et la mémoire.|Proteinantigene sind T-abhängig: B-Zellen brauchen CD40L und Zytokine von T-Helferzellen für Klassenwechsel und Gedächtnis."],
    ["Their response to the capsular polysaccharide is…|Leur réponse au polysaccharide capsulaire est…|Ihre Antwort auf das Kapselpolysaccharid ist …", ["largely preserved (mostly IgM)|largement conservée (surtout IgM)|weitgehend erhalten (vor allem IgM)", "absent|absente|fehlend", "mainly IgG with memory|surtout IgG avec mémoire|vor allem IgG mit Gedächtnis", "mainly cytotoxic T cells|surtout lymphocytes T cytotoxiques|vor allem zytotoxische T-Zellen"], "Repetitive polysaccharides cross-link B-cell receptors without T help – why conjugate vaccines link them to a protein.|Les polysaccharides répétitifs pontent les récepteurs B sans aide T – d'où les vaccins conjugués à une protéine.|Repetitive Polysaccharide vernetzen B-Zell-Rezeptoren ohne T-Hilfe – deshalb koppeln Konjugatimpfstoffe sie an ein Protein."]]),
  XP('pha', "Strips of guinea-pig trachea are contracted with increasing doses of acetylcholine. Atropine 1 nM shifts the dose–response curve to the right in parallel with the same maximum. Compound Z lowers the maximal contraction and cannot be overcome by more acetylcholine.|Des bandelettes de trachée de cobaye sont contractées par des doses croissantes d'acétylcholine. L'atropine 1 nM décale la courbe dose–réponse vers la droite, parallèlement, avec le même maximum. Le composé Z abaisse la contraction maximale, sans être surmonté par davantage d'acétylcholine.|Meerschweinchen-Trachealstreifen werden mit steigenden Acetylcholindosen kontrahiert. Atropin 1 nM verschiebt die Dosis-Wirkungs-Kurve parallel nach rechts bei gleichem Maximum. Substanz Z senkt die maximale Kontraktion und lässt sich durch mehr Acetylcholin nicht überwinden.", [
    ["Atropine behaves as a…|L'atropine se comporte comme un…|Atropin verhält sich wie ein …", ["reversible competitive antagonist|antagoniste compétitif réversible|reversibler kompetitiver Antagonist", "non-competitive antagonist|antagoniste non compétitif|nichtkompetitiver Antagonist", "partial agonist|agoniste partiel|partieller Agonist", "inverse agonist|agoniste inverse|inverser Agonist"], "A parallel right shift with unchanged maximum is the signature of competitive antagonism.|Un décalage parallèle vers la droite sans changement du maximum signe l'antagonisme compétitif.|Eine parallele Rechtsverschiebung bei unverändertem Maximum kennzeichnet kompetitiven Antagonismus."],
    ["With atropine present, the EC50 of acetylcholine…|En présence d'atropine, la CE50 de l'acétylcholine…|In Gegenwart von Atropin wird die EC50 von Acetylcholin …", ["increases (lower apparent potency)|augmente (puissance apparente plus faible)|größer (geringere scheinbare Potenz)", "decreases|diminue|kleiner", "is unchanged|reste inchangée|unverändert", "becomes zero|devient nulle|null"], "More agonist is needed for the same effect; efficacy (the maximum) is unchanged.|Il faut plus d'agoniste pour le même effet ; l'efficacité (maximum) reste la même.|Für dieselbe Wirkung braucht man mehr Agonist; die Wirksamkeit (Maximum) bleibt gleich."],
    ["Compound Z most likely…|Le composé Z est le plus probablement…|Substanz Z ist am ehesten …", ["a non-competitive (or irreversible) antagonist|un antagoniste non compétitif (ou irréversible)|ein nichtkompetitiver (oder irreversibler) Antagonist", "a competitive antagonist|un antagoniste compétitif|ein kompetitiver Antagonist", "a full agonist|un agoniste entier|ein voller Agonist", "an acetylcholinesterase inhibitor|un inhibiteur de l'acétylcholinestérase|ein Acetylcholinesterase-Hemmer"], "A lowered maximum that more agonist cannot restore means fewer functional receptors or a block downstream.|Un maximum abaissé que l'agoniste ne peut restaurer signifie moins de récepteurs fonctionnels ou un blocage en aval.|Ein gesenktes Maximum, das mehr Agonist nicht wiederherstellt, bedeutet weniger funktionsfähige Rezeptoren oder eine Blockade weiter unten."]],
    {vb:{t:"Dose–response curves, potency and efficacy: Pharmacodynamics (R7).|Courbes dose–réponse, puissance et efficacité : Pharmacodynamie (R7).|Dosis-Wirkungs-Kurven, Potenz und Wirksamkeit: Pharmakodynamik (R7).", d:'pd'}}),
  XP('pha', "In a randomised trial, 2000 patients at high cardiovascular risk received a statin or placebo for 5 years. Heart attacks occurred in 4 % of the statin group and 6 % of the placebo group (relative risk 0.67, 95 % CI 0.52–0.88, p = 0.004).|Dans un essai randomisé, 2000 patients à haut risque cardiovasculaire ont reçu une statine ou un placebo pendant 5 ans. Des infarctus sont survenus chez 4 % du groupe statine et 6 % du groupe placebo (risque relatif 0,67, IC 95 % 0,52–0,88, p = 0,004).|In einer randomisierten Studie erhielten 2000 Patienten mit hohem kardiovaskulärem Risiko 5 Jahre lang ein Statin oder Placebo. Herzinfarkte traten bei 4 % der Statin- und 6 % der Placebogruppe auf (relatives Risiko 0,67, 95-%-KI 0,52–0,88, p = 0,004).", [
    ["Absolute risk reduction over 5 years?|Réduction absolue du risque sur 5 ans ?|Absolute Risikoreduktion über 5 Jahre?", ["2 %|2 %|2 %", "33 %|33 %|33 %", "67 %|67 %|67 %", "4 %|4 %|4 %"], "6 % − 4 % = 2 percentage points; 33 % is the relative risk reduction.|6 % − 4 % = 2 points ; 33 % est la réduction relative du risque.|6 % − 4 % = 2 Prozentpunkte; 33 % ist die relative Risikoreduktion."],
    ["Number needed to treat for 5 years to prevent one heart attack?|Nombre de sujets à traiter 5 ans pour éviter un infarctus ?|Number needed to treat über 5 Jahre, um einen Herzinfarkt zu verhindern?", ["50|50|50", "3|3|3", "25|25|25", "100|100|100"], "NNT = 1 ÷ 0.02 = 50.|NST = 1 ÷ 0,02 = 50.|NNT = 1 ÷ 0,02 = 50."],
    ["Which statement is correct?|Quelle affirmation est exacte ?|Welche Aussage stimmt?", ["The reduction is statistically significant – the 95 % CI excludes 1|La réduction est significative – l'IC à 95 % exclut 1|Die Reduktion ist signifikant – das 95-%-KI schließt 1 aus", "The result is not significant because the CI is wide|Le résultat n'est pas significatif car l'IC est large|Das Ergebnis ist nicht signifikant, weil das KI breit ist", "p = 0.004 means a 0.4 % chance that the statin works|p = 0,004 signifie 0,4 % de chances que la statine soit efficace|p = 0,004 heißt 0,4 % Wahrscheinlichkeit, dass das Statin wirkt", "The statin prevents 67 % of heart attacks|La statine prévient 67 % des infarctus|Das Statin verhindert 67 % der Herzinfarkte"], "A CI for a ratio that does not include 1 means significance at the 5 % level; p is the chance of data this extreme if there were no effect.|Un IC de rapport qui n'inclut pas 1 signifie une significativité au seuil de 5 % ; p est la probabilité de données aussi extrêmes en l'absence d'effet.|Ein KI eines Verhältnisses ohne die 1 bedeutet Signifikanz auf dem 5-%-Niveau; p ist die Wahrscheinlichkeit so extremer Daten ohne Effekt."]],
    {vb:{t:"Practise ARR, RRR and NNT with new numbers: Risk & treatment effects (T2).|Entraînez-vous aux RAR, RRR et NST avec de nouveaux chiffres : Risque et effet des traitements (T2).|ARR, RRR und NNT mit neuen Zahlen üben: Risiko & Therapieeffekte (T2).", d:'riskstat'}})
];
